def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    centers=[]
    for r in range(1,h-1):
        for c in range(1,w-1):
            if g[r][c]==2 and all(g[r+dr][c+dc]==3 for dr in (-1,0,1) for dc in (-1,0,1) if (dr,dc)!=(0,0)):
                centers.append((r,c))
    # Grid rails are the persistent straight rows or columns of color 2.
    rails=[c for c in range(w) if sum(grid[r][c]==2 for r in range(h))>=h-2]
    if not rails:
        rails=[c for c in range(w) if any(grid[r][c]==2 for r in range(h))]
    def paint(r,c):
        if 0<=r<h and 0<=c<w and g[r][c]==0:
            g[r][c]=1
    for r,c in centers:
        # Each symbol sends a 1-colored horizontal signal, and stamps a
        # 3x3 perimeter at every other vertical rail along that row.
        for x in range(w):
            paint(r,x)
        for rail in rails:
            if rail==c: continue
            for dr in (-1,0,1):
                for dc in (-1,0,1):
                    paint(r+dr,rail+dc)
    return g
