def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if g[r][c] == 2 and all(
                g[r + dr][c + dc] == 3
                for dr in (-1, 0, 1) for dc in (-1, 0, 1)
                if (dr, dc) != (0, 0)
            ):
                centers.append((r, c))
    # Long rows/columns of 2 form the rails; rings replace parts of rails.
    vrails = [c for c in range(w) if sum(grid[r][c] == 2 for r in range(h)) >= h - 3]
    hrails = [r for r in range(h) if sum(v == 2 for v in grid[r]) >= w - 3]

    def set_one(r, c):
        if 0 <= r < h and 0 <= c < w and g[r][c] != 3:
            g[r][c] = 1

    for r, c in centers:
        if c in vrails:
            # Marker lies on a vertical rail: cast a horizontal ray.
            for x in range(w):
                if g[r][x] == 0:
                    g[r][x] = 1
            for rail in vrails:
                if rail != c:
                    for rr in range(r - 1, r + 2):
                        for cc in range(rail - 1, rail + 2):
                            if (rr, cc) != (r, rail):
                                set_one(rr, cc)
        elif r in hrails:
            # Marker lies on a horizontal rail: cast a vertical ray.
            for y in range(h):
                if g[y][c] == 0:
                    g[y][c] = 1
            for rail in hrails:
                if rail != r:
                    for rr in range(rail - 1, rail + 2):
                        for cc in range(c - 1, c + 2):
                            if (rr, cc) != (rail, c):
                                set_one(rr, cc)
    return g
